#define DEFINE_CALLBACK(NAME, ...) \
	void mCoreCallback(NAME) (void* context) { \
		struct mScriptContext* scriptContext = context; \
		if (!scriptContext) { \
			return; \
		} \
		__VA_ARGS__ \
		mScriptContextTriggerCallback(scriptContext, #NAME, NULL); \
	}

