 680	static void _clearMemoryMap(struct mScriptContext* context, struct mScriptCoreAdapter* adapter, bool clear) {
 681		struct TableIterator iter;
 682		if (mScriptTableIteratorStart(&adapter->memory, &iter)) {
 683			while (true) {
 684				struct mScriptValue* weakref = mScriptTableIteratorGetValue(&adapter->memory, &iter);
 685				if (weakref) {
 686					if (clear) {
 687						mScriptContextClearWeakref(context, weakref->value.s32);
 688					}
 689					mScriptValueDeref(weakref);
 690				}
 691				if (!mScriptTableIteratorNext(&adapter->memory, &iter)) {
 692					break;
 693				}
 694			}
 695		}
 696		mScriptTableClear(&adapter->memory);
 697	}
