 699	static void _rebuildMemoryMap(struct mScriptContext* context, struct mScriptCoreAdapter* adapter) {
 700		_clearMemoryMap(context, adapter, true);
 701	
 702		const struct mCoreMemoryBlock* blocks;
 703		size_t nBlocks = adapter->core->listMemoryBlocks(adapter->core, &blocks);
 704		size_t i;
 705		for (i = 0; i < nBlocks; ++i) {
 706			if (blocks[i].flags == mCORE_MEMORY_VIRTUAL) {
 707				continue;
 708			}
 709			struct mScriptMemoryDomain* memadapter = calloc(1, sizeof(*memadapter));
 710			memadapter->core = adapter->core;
 711			memcpy(&memadapter->block, &blocks[i], sizeof(memadapter->block));
 712			struct mScriptValue* value = mScriptValueAlloc(mSCRIPT_TYPE_MS_S(mScriptMemoryDomain));
 713			value->flags = mSCRIPT_VALUE_FLAG_FREE_BUFFER;
 714			value->value.opaque = memadapter;
 715			struct mScriptValue* key = mScriptStringCreateFromUTF8(blocks[i].internalName);
 716			mScriptTableInsert(&adapter->memory, key, mScriptContextMakeWeakref(context, value));
 717			mScriptValueDeref(key);
 718		}
 719	}
